// @generated by:gauntlet run:godseye-local-orchestration
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  type OrchestrationFixture,
  orchestrationFixture,
} from "./helpers/orchestration-fixture.js";
import { repository } from "./helpers.js";

describe("cross-provider orchestration and bounded dependency context", () => {
  let f: OrchestrationFixture;
  beforeEach(async () => {
    f = await orchestrationFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });

  it("T-AC-704 runs an exact prepared coding child then quotes its result to an approved Hermes consumer", async () => {
    const preparation = await f.prepareCoding();
    const plan = await f.prepare({
      steps: [
        {
          id: "patch",
          dependsOn: [],
          kind: "coding",
          preparationId: preparation.id,
          expectedHash: preparation.hash,
        },
        { ...f.research, dependsOn: ["patch"], includeDependencyOutputs: true },
      ],
    });
    await f.approve(plan);
    await f.tick();
    await f.work();
    await f.tick();
    await f.work();
    await f.tick();
    expect((await f.detail(plan.plan.id)).state).toBe("succeeded");
    expect(f.provider.submissions).toHaveLength(1);
    expect(f.agentProvider.submissions).toHaveLength(1);
    expect(f.agentProvider.submissions[0]?.input).toContain("A bounded synthetic patch");
    expect(f.agentProvider.submissions[0]?.input).toContain("inert untrusted data");
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(2);
  });

  it("T-AC-706 overflowing dependency context fails its plan while an unrelated plan continues", async () => {
    f.agentProvider.inspectScript = async (request) => ({
      state: "succeeded",
      providerRunId: request.providerRunId,
      stopped: true,
      output: "x".repeat(8192),
    });
    const overflowing = await f.prepare({
      steps: [
        f.research,
        { ...f.research, id: "consumer", dependsOn: ["research"], includeDependencyOutputs: true },
      ],
    });
    await f.approve(overflowing);
    await f.tick();
    await f.work();
    const unrelated = await f.prepare({
      steps: [
        {
          id: "question",
          dependsOn: [],
          kind: "clarification",
          question: "Independent owner question",
        },
      ],
      maxCostMicros: 0,
    });
    await f.approve(unrelated);
    await f.tick();
    expect((await f.detail(overflowing.plan.id)).state).toBe("failed");
    expect((await f.detail(unrelated.plan.id)).state).toBe("waiting_clarification");
    expect(f.agentProvider.submissions).toHaveLength(1);
  });

  it("T-AC-706 expired delegated work cannot stop a later unrelated owner task", async () => {
    const plan = await f.prepare({ lifetimeSeconds: 30 });
    await f.approve(plan);
    await f.tick();
    f.clock.advance(30001);
    await f.work();
    const task = await f.infrastructure.agents.launch(
      f.freshOwner(),
      {
        profileId: f.profile.id,
        expectedRevision: f.profile.revision,
        input: "Independent owner request",
      },
      randomUUID(),
    );
    await f.work();
    expect((await f.infrastructure.agents.detail(f.freshOwner(), task.id)).task.state).toBe(
      "succeeded",
    );
    expect(f.agentProvider.submissions.map((row) => row.input)).toEqual([
      "Independent owner request",
    ]);
  });

  it.each(["profile", "repository", "budget"] as const)(
    "T-AC-706 rejects new admission after approved %s authority changes",
    async (change) => {
      const plan = await f.prepare();
      await f.approve(plan);
      if (change === "profile")
        await f.infrastructure.agents.pause(
          f.freshOwner(),
          f.profile.id,
          { expectedRevision: f.profile.revision },
          randomUUID(),
        );
      if (change === "repository")
        await f.core.configureRepository(
          f.freshOwner(),
          f.project.id,
          { ...repository, branch: "changed-after-approval" },
          f.project.revision,
          randomUUID(),
        );
      if (change === "budget")
        await f.infrastructure.foundation.configureBudget(
          f.freshOwner(),
          f.project.id,
          { limitMicros: 0, expectedRevision: 2 },
          randomUUID(),
        );
      await f.tick();
      expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(0);
      expect(f.agentProvider.submissions).toHaveLength(0);
      expect((await f.detail(plan.plan.id)).state).not.toBe("succeeded");
    },
  );

  it("T-AC-707 quarantines a coding child whose physical stop throws without blocking other plans", async () => {
    f.provider.submitScript = async () => ({
      state: "unknown",
      stopped: false,
      grantsRevoked: false,
      workspace: "retained",
    });
    f.provider.stop = async () => {
      throw new Error("Synthetic coding stop transport failure");
    };
    const preparation = await f.prepareCoding();
    const plan = await f.prepare({
      steps: [
        {
          id: "patch",
          dependsOn: [],
          kind: "coding",
          preparationId: preparation.id,
          expectedHash: preparation.hash,
        },
      ],
    });
    await f.approve(plan);
    await f.tick();
    await f.work();
    await f.tick();
    await f.infrastructure.orchestration.cancel(f.freshOwner(), plan.plan.id, randomUUID());
    const unrelated = await f.prepare({
      maxCostMicros: 0,
      steps: [
        {
          id: "question",
          dependsOn: [],
          kind: "clarification",
          question: "Independent owner clarification",
        },
      ],
    });
    await f.approve(unrelated);
    await f.tick();
    const stopped = await f.detail(plan.plan.id),
      taskId = stopped.children[0]?.taskId;
    if (!taskId) throw new Error("Missing retained coding child");
    expect(stopped.reason).toBe("CLEANUP_UNCERTAIN");
    expect((await f.infrastructure.coding.detail(f.freshOwner(), taskId)).task.cleanupState).toBe(
      "quarantined",
    );
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(preparation.limits.maxCostMicros);
    expect((await f.detail(unrelated.plan.id)).state).toBe("waiting_clarification");
    expect(f.provider.submissions).toHaveLength(1);
  });
});
